# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 235" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="235" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">III. SELİM VE II. MAHMUT DÖNEMİ MODERNLEŞME VE OTORİTE HAMLELERİ</text>\n  <rect x="20" y="44" width="320" height="174" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="180" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">III. SELİM DÖNEMİ (1789 - 1807)</text>\n  <rect x="34" y="78" width="292" height="126" rx="6" fill="#ffffff" stroke="#93c5fd"/>\n  <text x="180" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Nizam-ı Cedit (Yeni Düzen) Reformları</text>\n  <text x="180" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Islahatlar için devlet adamlarına lâyiha hazırlatılması.</text>\n  <text x="180" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• Nizam-ı Cedit Ordusu ve İrad-ı Cedit Hazinesi.</text>\n  <text x="180" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Avrupa\'da ilk daimî elçiliklerin (Londra vb.) açılması.</text>\n  <text x="180" y="172" text-anchor="middle" font-size="9.5" fill="#334155">• Mühendishane-i Berrî-i Hümayun\'un geliştirilmesi.</text>\n  <rect x="360" y="44" width="320" height="174" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="520" y="66" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">II. MAHMUT DÖNEMİ (1808 - 1839)</text>\n  <rect x="374" y="78" width="292" height="126" rx="6" fill="#ffffff" stroke="#fcd34d"/>\n  <text x="520" y="98" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Merkezîleşme ve Kurumsal Dönüşüm</text>\n  <text x="520" y="118" text-anchor="middle" font-size="9.5" fill="#334155">• Sened-i İttifak (1808): Padişah yetkisinin ilk kez sınırlanması.</text>\n  <text x="520" y="136" text-anchor="middle" font-size="9.5" fill="#334155">• Vak\'a-i Hayriye (1826): Yeniçeri Ocağının kaldırılması.</text>\n  <text x="520" y="154" text-anchor="middle" font-size="9.5" fill="#334155">• Nazırlıklar (Bakanlıklar), muhtarlıklar ve posta teşkilatı.</text>\n  <text x="520" y="172" text-anchor="middle" font-size="9.5" fill="#334155">• Takvim-i Vekayi (ilk resmî gazete) ve Tıbbiye/Harbiye.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">OSMANLI HUKUK VE DEMOKRATİKLEŞME ADIMLARI ZAMAN ŞERİDİ (1808 - 1908)</text>\n  <rect x="18" y="46" width="124" height="156" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="80" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">1808</text>\n  <text x="80" y="86" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Sened-i İttifak</text>\n  <text x="80" y="110" text-anchor="middle" font-size="8.8" fill="#334155">Padişah ile ayanlar</text>\n  <text x="80" y="126" text-anchor="middle" font-size="8.8" fill="#334155">arasında sözleşme;</text>\n  <text x="80" y="142" text-anchor="middle" font-size="8.8" fill="#334155">padişah yetkisinin</text>\n  <text x="80" y="158" text-anchor="middle" font-size="8.8" font-weight="bold" fill="#92400e">ilk kez sınırlanması.</text>\n  <rect x="154" y="46" width="124" height="156" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="216" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1e40af">1839</text>\n  <text x="216" y="86" text-anchor="middle" font-size="10" font-weight="bold" fill="#1d4ed8">Tanzimat Fermanı</text>\n  <text x="216" y="110" text-anchor="middle" font-size="8.8" fill="#334155">Can, mal, ırz güvenliği;</text>\n  <text x="216" y="126" text-anchor="middle" font-size="8.8" fill="#334155">gelire göre vergi;</text>\n  <text x="216" y="142" text-anchor="middle" font-size="8.8" fill="#334155">kanun üstünlüğünün</text>\n  <text x="216" y="158" text-anchor="middle" font-size="8.8" font-weight="bold" fill="#1e40af">ilk kez kabulü.</text>\n  <rect x="290" y="46" width="124" height="156" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="352" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#166534">1856</text>\n  <text x="352" y="86" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Islahat Fermanı</text>\n  <text x="352" y="110" text-anchor="middle" font-size="8.8" fill="#334155">Gayrimüslimlere devlet</text>\n  <text x="352" y="126" text-anchor="middle" font-size="8.8" fill="#334155">memurluğu, okul açma</text>\n  <text x="352" y="142" text-anchor="middle" font-size="8.8" fill="#334155">ve yerel meclislere</text>\n  <text x="352" y="158" text-anchor="middle" font-size="8.8" font-weight="bold" fill="#166534">katılım hakkı.</text>\n  <rect x="426" y="46" width="124" height="156" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="488" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#6b21a8">1876</text>\n  <text x="488" y="86" text-anchor="middle" font-size="10" font-weight="bold" fill="#7e22ce">I. Meşrutiyet</text>\n  <text x="488" y="110" text-anchor="middle" font-size="8.8" fill="#334155">İlk anayasa Kanun-ı</text>\n  <text x="488" y="126" text-anchor="middle" font-size="8.8" fill="#334155">Esasi ve Meclis-i</text>\n  <text x="488" y="142" text-anchor="middle" font-size="8.8" fill="#334155">Mebusan ile halkın</text>\n  <text x="488" y="158" text-anchor="middle" font-size="8.8" font-weight="bold" fill="#6b21a8">yönetime katılımı.</text>\n  <rect x="562" y="46" width="120" height="156" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="1.8"/>\n  <text x="622" y="68" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#991b1b">1908</text>\n  <text x="622" y="86" text-anchor="middle" font-size="10" font-weight="bold" fill="#b91c1c">II. Meşrutiyet</text>\n  <text x="622" y="110" text-anchor="middle" font-size="8.8" fill="#334155">Meclisin yeniden</text>\n  <text x="622" y="126" text-anchor="middle" font-size="8.8" fill="#334155">açılması, çok partili</text>\n  <text x="622" y="142" text-anchor="middle" font-size="8.8" fill="#334155">siyasi hayat ve</text>\n  <text x="622" y="158" text-anchor="middle" font-size="8.8" font-weight="bold" fill="#991b1b">hükûmetin meclise</text>\n  <text x="622" y="172" text-anchor="middle" font-size="8.8" font-weight="bold" fill="#991b1b">sorumlu kılınması.</text>\n</svg>', '<svg viewBox="0 0 700 225" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="225" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DAĞILMAYI ÖNLEMEK AMACIYLA GELİŞTİRİLEN DÖRT FİKİR AKIMI</text>\n  <rect x="20" y="46" width="152" height="158" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="96" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. OSMANLICILIK</text>\n  <text x="96" y="92" text-anchor="middle" font-size="9" fill="#334155">• Din ve ırk ayrımı olmadan</text>\n  <text x="96" y="108" text-anchor="middle" font-size="9" fill="#334155">eşit \'Osmanlı yurttaşı\'</text>\n  <text x="96" y="124" text-anchor="middle" font-size="9" fill="#334155">kimliği oluşturmak.</text>\n  <text x="96" y="148" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">Temsilciler: Namık Kemal,</text>\n  <text x="96" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#1d4ed8">Mithat Paşa, Ziya Paşa</text>\n  <rect x="188" y="46" width="152" height="158" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="264" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. İSLAMCILIK</text>\n  <text x="264" y="92" text-anchor="middle" font-size="9" fill="#334155">• Müslüman milletleri</text>\n  <text x="264" y="108" text-anchor="middle" font-size="9" fill="#334155">halifelik makamı etrafında</text>\n  <text x="264" y="124" text-anchor="middle" font-size="9" fill="#334155">kenetlemek (Ümmetçilik).</text>\n  <text x="264" y="148" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">Temsilciler: Mehmet Akif</text>\n  <text x="264" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#15803d">Ersoy, Said Halim Paşa</text>\n  <rect x="356" y="46" width="152" height="158" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="432" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">3. TÜRKÇÜLÜK</text>\n  <text x="432" y="92" text-anchor="middle" font-size="9" fill="#334155">• Türk unsurunu dil, tarih</text>\n  <text x="432" y="108" text-anchor="middle" font-size="9" fill="#334155">ve kültür birliği etrafında</text>\n  <text x="432" y="124" text-anchor="middle" font-size="9" fill="#334155">bütünleştirmek.</text>\n  <text x="432" y="148" text-anchor="middle" font-size="9" font-weight="bold" fill="#b45309">Temsilciler: Ziya Gökalp,</text>\n  <text x="432" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#b45309">Yusuf Akçura, M. Emin</text>\n  <rect x="524" y="46" width="156" height="158" rx="10" fill="#fae8ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="602" y="70" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. BATICILIK</text>\n  <text x="602" y="92" text-anchor="middle" font-size="9" fill="#334155">• Bilim, teknik, hukuk ve</text>\n  <text x="602" y="108" text-anchor="middle" font-size="9" fill="#334155">toplumsal kurumlarda</text>\n  <text x="602" y="124" text-anchor="middle" font-size="9" fill="#334155">Avrupa\'yı örnek almak.</text>\n  <text x="602" y="148" text-anchor="middle" font-size="9" font-weight="bold" fill="#7e22ce">Temsilciler: Tevfik Fikret,</text>\n  <text x="602" y="164" text-anchor="middle" font-size="9" font-weight="bold" fill="#7e22ce">Abdullah Cevdet</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
